package com.ecole.gestion_scolaire.hr.controller; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*; @RestController @RequestMapping("/api/hr/teaching-assignments") public class TeachingAssignmentController { private final TeachingAssignmentService service; public TeachingAssignmentController(TeachingAssignmentService s){service=s;} @PostMapping @PreAuthorize("hasAuthority('ENSEIGNANT_AFFECTER')") public ResponseEntity<TeachingAssignmentResponse> create(@Valid @RequestBody TeachingAssignmentRequest q){return ResponseEntity.status(201).body(service.create(q));} @GetMapping("/teacher/{teacherId}") @PreAuthorize("hasAuthority('ENSEIGNANT_CONSULTER')") public List<TeachingAssignmentResponse> teacher(@PathVariable Long teacherId){return service.byTeacher(teacherId);} @GetMapping("/class/{classId}") @PreAuthorize("hasAuthority('ENSEIGNANT_CONSULTER')") public List<TeachingAssignmentResponse> classe(@PathVariable Long classId,@RequestParam Long schoolYearId){return service.byClass(schoolYearId,classId);} @PatchMapping("/{id}/end") @PreAuthorize("hasAuthority('ENSEIGNANT_AFFECTER')") public TeachingAssignmentResponse end(@PathVariable Long id,@RequestParam LocalDate date){return service.end(id,date);} }